def runs(grid):
    out=[]
    for row in grid:
        c=0; cur=None
        for x in row:
            if x!=0 and x==cur: c+=1
            else:
                if cur is not None and cur!=0: out.append((cur,c))
                cur=x; c=1 if x!=0 else 0
        if cur not in (None,0): out.append((cur,c))
    return out

def transform(g):
    rs=runs(g)
    # order colors by first appearance in reading order
    order=[]
    for c,_ in rs:
        if c not in order: order.append(c)
    seq=[]
    for c in sorted(order, reverse=True):
        seq += [c]*sum(1 for cc,_ in rs if cc==c)
    while len(seq)<6: seq.append(0)
    return [seq[:3], seq[3:6]]

